Общий disabled удалён; ограничение остаётся на «Добавить». padding перед background включает отступ в область синего фона; сброс с 3 даёт 0 и сумму 0.

import SwiftUI
struct CartItem {
    let id = 18
    var quantity = 1
    var express = false
    var total: Int { quantity * 300 + (express ? 100 : 0) }
}
struct CartScreen: View {
    @State private var item = CartItem()
    var body: some View {
        VStack {
            Text("Сумма: \(item.total) ₽")
            DeliveryControl(express: $item.express)
        }
    }
}
struct DeliveryControl: View {
    @Binding var express: Bool
    var body: some View {
        Toggle("Экспресс +100", isOn: $express)
    }
}

Toggle пишет через Binding в item.express у владельца. Включение даёт 400, выключение возвращает 300; ребёнок не хранит отдельный флаг или сумму.

import SwiftUI
struct CartItem {
    let id = 18
    var quantity = 2
    var coupon = false
    var total: Int { quantity * (coupon ? 250 : 300) }
}
struct CartScreen: View {
    @State private var item = CartItem()
    var body: some View {
        VStack {
            Text("Сумма: \(item.total) ₽")
            CouponControl(applied: item.coupon) { item.coupon = true }
        }
    }
}
struct CouponControl: View {
    let applied: Bool
    let onApply: () -> Void
    var body: some View {
        Button("Применить скидку", action: onApply).disabled(applied)
    }
}

Сумма вычисляется из количества и coupon. Действие устанавливает true, поэтому повторный вызов не накапливает скидку; disabled относится к кнопке, а не ко всему экрану.
